import csv
tsid = "738ac87b-0db5-5085-9c36-eb153052549e"
vals = []
with open(VALUES_CSV) as f:
    r = csv.reader(f)
    hdr = next(r)
    for row in r:
        if row[0] == tsid and row[1] >= "2018-10-03 07:59" and row[1] <= "2018-10-03 18:01":
            ts = row[1]
            # filter between 08:00 and 18:00 inclusive
            if ts.startswith("2018-10-03"):
                hr = int(ts[11:13])
                if 8 <= hr <= 18:
                    vals.append((ts, float(row[2])))
for v in vals: print(v)
print("count", len(vals))
if vals:
    print("mean", sum(x[1] for x in vals)/len(vals))

